import{_ as a,c as r,o as n,ag as i}from"./chunks/framework.B-XtCDNB.js";const u=JSON.parse('{"title":"Genie Programming Language","description":"Genie Programming Language Genie is a programming language in the same vein as Vala. It allows for a more modern, indentation-based programming style while being able to effortlessly create and use...","frontmatter":{},"headers":[],"relativePath":"genie/index.md","filePath":"genie/index.md","lastUpdated":1785763655000}'),t={name:"genie/index.md"};function o(l,e,s,g,d,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="genie-programming-language" tabindex="-1">Genie Programming Language <a class="header-anchor" href="#genie-programming-language" aria-label="Permalink to &quot;Genie Programming Language&quot;">​</a></h1><p>Genie is a programming language in the same vein as <a href="https://vala.dev" target="_blank" rel="noreferrer">Vala</a>. It allows for a more modern, indentation-based programming style while being able to effortlessly create and use <a href="https://docs.gtk.org/gobject/" target="_blank" rel="noreferrer">GObjects</a> natively. Like Vala, Genie produces C code that compiles to executable binaries, so programs written in Genie have performance and resource usage similar to those written directly in Vala and C.</p><p>Genie shares the Vala compiler (<code>valac</code>); a <code>.gs</code> file simply uses a different parser. As a result, Vala and Genie code can be freely mixed in the same project.</p><ul class="section-toc"><li><a href="introduction">Introduction to Genie</a> — language overview, syntax, and tutorial (multiple chapters)</li><li><a href="/genie/sample-code/">Sample code</a> — full Genie sources (basic I/O, Cairo, GIO, LibSoup, XML, and more)</li><li><a href="developing-genie">Developing Genie</a> - how to contribute to the Genie scanner and parser</li><li><a href="resources">Tutorials, Blogs and Code Examples</a> - external Genie learning resources and projects</li></ul><h2 id="external-resources" tabindex="-1">External Resources <a class="header-anchor" href="#external-resources" aria-label="Permalink to &quot;External Resources&quot;">​</a></h2><ul><li><a href="https://valadoc.org" target="_blank" rel="noreferrer">Valadoc.org</a> - API reference for the GLib, GObject and other bindings used by Genie</li></ul>',6)])])}const p=a(t,[["render",o]]);export{u as __pageData,p as default};
